codeExamples.code:
-- 1. Create a storage credential backed by an IAM role (created in the customer account)
CREATE STORAGE CREDENTIAL s3_data_cred
  WITH (
    AWS_IAM_ROLE = 'arn:aws:iam::123456789012:role/dbx-uc-access'
  )
  COMMENT 'Role for accessing the data lake bucket';

-- 2. Define the external location (the storage path the data plane may use)
CREATE EXTERNAL LOCATION lake_bronze
  URL 's3://acme-data-lake/bronze'
  WITH (STORAGE CREDENTIAL s3_data_cred);

-- 3. Grant least-privilege access to a group
GRANT READ FILES, WRITE FILES ON EXTERNAL LOCATION lake_bronze TO `data_engineers`;
